package com.opensocket.aievent.core.iam.persistence.repository;
import static com.opensocket.aievent.core.iam.persistence.repository.RowValues.*;import com.opensocket.aievent.core.iam.authentication.application.port.out.*;import com.opensocket.aievent.core.iam.authentication.domain.*;import com.opensocket.aievent.core.iam.persistence.dao.IamAuthenticationDao;import com.opensocket.aievent.core.iam.persistence.exception.IamOptimisticLockException;import com.opensocket.aievent.database.persistence.spi.DatabaseRepositoryAdapter;import java.time.Instant;import java.util.*;
@DatabaseRepositoryAdapter public class MybatisAuthenticationStateRepository implements SubjectSecurityStateRepository,LoginAttemptRepository{private final IamAuthenticationDao dao;public MybatisAuthenticationStateRepository(IamAuthenticationDao dao){this.dao=dao;}public Optional<SubjectSecurityState>find(CredentialSubjectType t,String id){return Optional.ofNullable(dao.findSecurityState(t.name(),id)).map(r->SubjectSecurityState.reconstitute(t,id,intValue(r,"failedLoginCount"),Optional.ofNullable(instant(r,"lockedUntil")),Optional.ofNullable(instant(r,"lastSuccessAt")),longValue(r,"version")));}public SubjectSecurityState save(SubjectSecurityState s,long expected){Map<String,Object>r=new HashMap<>();r.put("subjectType",s.subjectType().name());r.put("subjectId",s.subjectId());r.put("failedLoginCount",s.failedLoginCount());r.put("lockedUntil",s.lockedUntil().orElse(null));r.put("lastSuccessAt",s.lastSuccessAt().orElse(null));r.put("version",s.version());int n=expected==0?dao.insertSecurityState(r):dao.updateSecurityState(r,expected);if(n!=1)throw new IamOptimisticLockException("SubjectSecurityState",s.subjectId(),expected);return s;}public void append(LoginAttempt a){Map<String,Object>r=new HashMap<>();r.put("attemptId",a.attemptId());r.put("normalizedUsername",a.normalizedUsername());r.put("subjectId",a.subjectId());r.put("tenantId",a.tenantId());r.put("successful",a.successful());r.put("reasonCode",a.reasonCode());r.put("ipAddress",a.ipAddress());r.put("userAgent",a.userAgent());r.put("correlationId",a.correlationId());r.put("attemptedAt",a.attemptedAt());dao.insertLoginAttempt(r);}public long countRecentFailures(String username,Instant since){return dao.countRecentFailures(username,since);}public long countRecentFailuresByIp(String ip,Instant since){return dao.countRecentFailuresByIp(ip,since);}}
